with joined as (select a.*, p.opened_date, p.store_name, p.sqft from inventory a left join stores p on a.store_id = p.id) select product_id, date_trunc('year', last_restock) as year_start, round(avg(quantity), 2) as avg_quantity, count(*) as row_count, count(*) as row_count_2, grouping_id() as gid from joined group by grouping sets ((product_id, date_trunc('year', last_restock)), (product_id)) having row_count_2 > 1 order by year_start desc;
